sealed class BridgeException: kotlin.Exception() {

    class InvalidState(
        ) : BridgeException() {
        override val message
            get() = ""
    }

    class StaleOperation(
        ) : BridgeException() {
        override val message
            get() = ""
    }

    class InternalFailure(
        ) : BridgeException() {
        override val message
            get() = ""
    }

    class InvalidPixels(
        ) : BridgeException() {
        override val message
            get() = ""
    }

    class InvalidValue(
        ) : BridgeException() {
