            get() = ""
    }

    class Cancelled(
        ) : BridgeException() {
        override val message
            get() = ""
    }

    class StorageCorrupt(
        ) : BridgeException() {
        override val message
            get() = ""
    }

    class UnsupportedSchema(
        ) : BridgeException() {
        override val message
            get() = ""
    }

    class ProtectionUnavailable(
        ) : BridgeException() {
        override val message
            get() = ""
    }

    class WriteFailed(
        ) : BridgeException() {
        override val message
            get() = ""
    }

    class StorageUnavailable(
        ) : BridgeException() {
        override val message
            get() = ""
    }


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<BridgeException> {
        override fun lift(error_buf: RustBuffer.ByValue): BridgeException = FfiConverterTypeBridgeError.lift(error_buf)
    }


}

/**
 * @suppress
 */
public object FfiConverterTypeBridgeError : FfiConverterRustBuffer<BridgeException> {
    override fun read(buf: ByteBuffer): BridgeException {


        return when(buf.getInt()) {
            1 -> BridgeException.InvalidState()
            2 -> BridgeException.StaleOperation()
            3 -> BridgeException.InternalFailure()
            4 -> BridgeException.InvalidPixels()
            5 -> BridgeException.InvalidValue()
            6 -> BridgeException.InvalidBuffer()
            7 -> BridgeException.Cancelled()
            8 -> BridgeException.StorageCorrupt()
            9 -> BridgeException.UnsupportedSchema()
            10 -> BridgeException.ProtectionUnavailable()
            11 -> BridgeException.WriteFailed()
            12 -> BridgeException.StorageUnavailable()
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: BridgeException): ULong {
        return when(value) {
            is BridgeException.InvalidState -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is BridgeException.StaleOperation -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is BridgeException.InternalFailure -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is BridgeException.InvalidPixels -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is BridgeException.InvalidValue -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is BridgeException.InvalidBuffer -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is BridgeException.Cancelled -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is BridgeException.StorageCorrupt -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is BridgeException.UnsupportedSchema -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is BridgeException.ProtectionUnavailable -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is BridgeException.WriteFailed -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is BridgeException.StorageUnavailable -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
        }
    }

    override fun write(value: BridgeException, buf: ByteBuffer) {
        when(value) {
            is BridgeException.InvalidState -> {
                buf.putInt(1)
                Unit
            }
            is BridgeException.StaleOperation -> {
                buf.putInt(2)
                Unit
            }
            is BridgeException.InternalFailure -> {
                buf.putInt(3)
                Unit
            }
            is BridgeException.InvalidPixels -> {
                buf.putInt(4)
                Unit
            }
            is BridgeException.InvalidValue -> {
                buf.putInt(5)
                Unit
            }
            is BridgeException.InvalidBuffer -> {
                buf.putInt(6)
                Unit
            }
            is BridgeException.Cancelled -> {
                buf.putInt(7)
                Unit
            }
            is BridgeException.StorageCorrupt -> {
                buf.putInt(8)
                Unit
            }
            is BridgeException.UnsupportedSchema -> {
                buf.putInt(9)
                Unit
            }
            is BridgeException.ProtectionUnavailable -> {
                buf.putInt(10)
                Unit
            }
            is BridgeException.WriteFailed -> {
                buf.putInt(11)
                Unit
            }
            is BridgeException.StorageUnavailable -> {
                buf.putInt(12)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



sealed class CoreCleanupOutcome {

    object MovedToTrash : CoreCleanupOutcome()


    object MovedToRecentlyDeleted : CoreCleanupOutcome()


    data class Skipped(
        val `reason`: CoreCleanupReason) : CoreCleanupOutcome() {
        companion object
    }

    object Failed : CoreCleanupOutcome()




    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeCoreCleanupOutcome : FfiConverterRustBuffer<CoreCleanupOutcome>{
    override fun read(buf: ByteBuffer): CoreCleanupOutcome {
        return when(buf.getInt()) {
            1 -> CoreCleanupOutcome.MovedToTrash
            2 -> CoreCleanupOutcome.MovedToRecentlyDeleted
            3 -> CoreCleanupOutcome.Skipped(
                FfiConverterTypeCoreCleanupReason.read(buf),
                )
            4 -> CoreCleanupOutcome.Failed
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: CoreCleanupOutcome) = when(value) {
        is CoreCleanupOutcome.MovedToTrash -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is CoreCleanupOutcome.MovedToRecentlyDeleted -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is CoreCleanupOutcome.Skipped -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypeCoreCleanupReason.allocationSize(value.`reason`)
            )
